window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d02_akt101"]={"title": "Приложение 9", "pages": 59, "pagesTxt": ["[стр. 1]\nРазраб.\r\nИзм. Лист № докум. Подп. Дата\r\nПров.\r\nН.контр.\r\nУтв.\r\nЛит. Лист Листов\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата\r\nТехнический отчет по результатам \r\nпроведения диагностики футерованных \r\nтрубопроводов системы \r\nгидротранспорта \r\nТалнахской обогатительной фабрики\r\nЗФ ПАО «ГМК «Норильский никель»\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nГолубев И.А.\r\nЦапенко С.В.\r\nТолстова М.Н.\r\nСысуев С.О.\r\n1\r\nИнв. № подл. Справ.№ Перв.примен.\r\nООО «Норникель Cпутник»\r\nОбщество с ограниченной ответственностью\r\nРоссийская Федерация, 125130, г. Москва, Старопетровский проезд, д.11, корп.2, тел. (495) 787 04 58\r\nТЕХНИЧЕСКИЙ ОТЧЕТ\r\nпо результатам проведения диагностики\r\nфутерованных трубопроводов\r\nсистемы гидротранспорта\r\nТалнахской обогатительной фабрики\r\nЗФ ПАО «ГМК «Норильский никель»\r\nТОМ № 5. Водовод от УП №1 до пруда - накопителя,\r\nинв.№ 39400183632\r\nНа 59 листах\r\nМосква 2025 г.", "[стр. 2]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n2\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nЛист согласования\r\nТехнического отчета по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной фабрики\r\nЗФ ПАО «ГМК «Норильский никель»\r\nТом № 5. Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632\r\n№ \r\nп/п Должность Подпись Дата Ф.И.О.\r\n1.\r\nГлавный гидротехник\r\nТалнахского горно￾обогатительного комбината\r\nЗФ ПАО «ГМК «Норильский \r\nникель» \r\nН.В. Стадниченко\r\n2.\r\nНачальник гидротехнической \r\nлаборатории Центра по надзору \r\nза гидротехническими \r\nсооружениями ЗФ ПАО «ГМК \r\n«Норильский никель»\r\nИ.Е. Моисеев\r\n3.\r\nГлавный специалист \r\nгидротехнической лаборатории \r\nЦентра по надзору за \r\nгидротехническими \r\nсооружениями ЗФ ПАО «ГМК \r\n«Норильский никель»\r\nИ.А. Сорокин \r\n4.\r\nНачальник отдела мониторинга \r\nбезопасности ГТС Талнахской \r\nобогатительной фабрики\r\nВ.А. Чуланов \r\n5.\r\nДиректор центра диагностики \r\nЗФ ПАО «ГМК «Норильский \r\nникель»\r\nП.А. Слипец\r\n6.\r\nРуководитель направления по \r\nэнергоменеджменту\r\nООО «Норникель Спутник»\r\nС.В. Цапенко\r\n7. Генеральный директор ООО \r\n«ЦМЭ» Ю.Э. Шадрина", "[стр. 3]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n3\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nСОДЕРЖАНИЕ\r\n1 ВВЕДЕНИЕ ......................................................................................................................... 4\r\n2 КРАТКАЯ ХАРАКТЕРИСТИКА ОБЪЕКТА ДИАГНОСТИКИ ........................................................ 7\r\n3 РЕЗУЛЬТАТЫ ПРОВЕДЁННОЙ ДИАГНОСТИКИ...................................................................... 8\r\n3.1 Документальное обследование....................................................................................... 8\r\n3.2 Основной этап................................................................................................................ 9\r\n3.2.1 Визуальный контроль............................................................................................... 9\r\n3.2.2 Экспресс диагностика .............................................................................................. 9\r\n3.2.3 Расширенная диагностика........................................................................................ 9\r\n3.3 Контрольный этап .........................................................................................................10\r\n3.3.1 Внутритрубная телеинспекция ................................................................................10\r\n3.4 Инженерные расчеты ....................................................................................................10\r\n3.4.1 Гидравлический расчет ...........................................................................................10\r\n3.4.2 Расчет отбраковочной толщины..............................................................................11\r\n3.4.3 Расчет скорости коррозии .......................................................................................11\r\n3.4.4 Расчет остаточного ресурса трубопровода ..............................................................11\r\n3.5 Анализ результатов диагностики...................................................................................11\r\n3.6 Выводы и рекомендации................................................................................................12\r\n3.6.1 Мероприятия, направленные на обеспечение дальнейшей безопасной эксплуатации \r\nтрубопроводов ..................................................................................................................13\r\nПРИЛОЖЕНИЕ № 1 АКТУАЛЬНЫЕ СХЕМЫ ТЕХНОЛОГИЧЕСКИХ ТРУБОПРОВОДОВ .....................16\r\nПРИЛОЖЕНИЕ № 3 ПРОТОКОЛ БЕСКОНТАКТНОЙ МАГНИТОМЕТРИЧЕСКОЙ ДИАГНОСТИКИ......19\r\nПРИЛОЖЕНИЕ № 4 ПРОТОКОЛ ВИЗУАЛЬНОГО И ИЗМЕРИТЕЛЬНОГО КОНТРОЛЯ......................24\r\nПРИЛОЖЕНИЕ № 5 ПРОТОКОЛ ГЕОДЕЗИЧЕСКОГО ОБСЛЕДОВАНИЯ ТРУБОПРОВОДА ...............35\r\nПРИЛОЖЕНИЕ № 6 ПРОТОКОЛ УЛЬТРАЗВУКОВОЙ ТОЛЩИНОМЕТРИИ .....................................38\r\nПРИЛОЖЕНИЕ № 7 ПРОТОКОЛ УЛЬТРАЗВУКОВОЙ ТОЛЩИНОМЕТРИИ СКАНИРОВАНИЕМ .........43\r\nПРИЛОЖЕНИЕ № 9 ПРОТОКОЛ ПО ЗАМЕРАМ ТВЕРДОСТИ........................................................47\r\nПРИЛОЖЕНИЕ № 11 ГИДРАВЛИЧЕСКИЙ РАСЧЕТ ......................................................................52\r\nПРИЛОЖЕНИЕ № 12 РАСЧЕТ ОТБРАКОВОЧНОЙ ТОЛЩИНЫ СТЕНКИ ТРУБОПРОВОДА ...............54\r\nПРИЛОЖЕНИЕ № 13 РАСЧЕТ СКОРОСТИ КОРРОЗИИ И ОСТАТОЧНОГО РЕСУРСА \r\nТРУБОПРОВОДА.......................................................................................................................57", "[стр. 4]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n4\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n1 ВВЕДЕНИЕ\r\nТом № 5. Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632 является \r\nсоставной частью Технического отчета по результатам проведения диагностики \r\nфутерованных трубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель», в состав которого вошли документы, \r\nпредставленные в таблице 1.\r\nТаблица 1. Перечень документов, сформированных по результатам работы\r\n№ тома Наименование документа\r\nТом № 0\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТом №0. Общие сведения\r\nТом № 1\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТОМ № 1. Подготовительный этап\r\nТом № 2\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТом № 2. Водовод от плавучей насосной установки до НОВ, \r\nинв.№ 39400183632\r\nТом № 3\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТом № 3. Водовод от НОВ до УП №2,\r\nинв.№ 39400183632\r\nТом № 4\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТом № 4. Водовод от УП №1 до пруда - накопителя,\r\nинв.№ 39400183632\r\nТом № 5\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТом № 5. Водовод от УП №1 до пруда- накопителя, \r\nинв.№ 39400183632\r\nТом № 6\r\nТехнический отчет по результатам проведения диагностики футерованных \r\nтрубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики ЗФ ПАО «ГМК «Норильский никель»\r\nТом № 6. Физико-механические свойства материала футеровки и \r\nосновного металла трубопровода.\r\nРезультатом выполнения всех работ, обозначенных техническим заданием, \r\nявляются 6 томов отчета, составленные в отношении отдельных трубопроводов.\r\nТом 0 Технического отчета включает в себя:\r\n‒ описание использованных приборов неразрушающего контроля и методов \r\nдиагностики;", "[стр. 5]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n5\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n‒ рекомендации о применении комплексного подхода диагностики, состоящего из \r\nчетырех основных составляющих, таких как методическая часть, техническая часть, \r\nинформационная часть и организационная часть;\r\n‒ свод выводов и рекомендаций Томов 1 – 6 Технического отчета; \r\n‒ Программу проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский \r\nникель»;\r\n‒ Регламент проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский \r\nникель»;\r\n‒ Проект производства работ по диагностике футерованных трубопроводов \r\nсистемы гидротранспорта Талнахской обогатительной фабрики ЗФ ПАО «ГМК \r\n«Норильский никель»;\r\n‒ копии свидетельств об аттестации и аккредитации лабораторий \r\nнеразрушающего контроля;\r\n‒ копии свидетельств о членстве СРО;\r\n‒ копии свидетельств и протоколов об аттестации и обучении персонала, \r\nпроводившего диагностику;\r\n‒ копии свидетельств о поверке и калибровке приборов неразрушающего \r\nконтроля.\r\nРабота по диагностике футерованных трубопроводов системы гидротранспорта\r\nвыполнена в соответствии с разработанными Подрядчиком Программой, Регламентом и \r\nППР, которые были согласованы Заказчиком и ЭО. Инструментальная часть работ по \r\nдиагностике выполнялась по наряду-допуску на производство работ повышенной \r\nопасности.\r\nВ настоящем Томе № 5 Технического отчета представлены:\r\n‒ краткая характеристика объекта диагностики (технологического трубопровода);\r\n‒ результаты документального обследования;\r\n‒ результаты визуального контроля;\r\n‒ результаты экспресс диагностики:\r\n̵ протокол бесконтактной магнитометрическая диагностика;\r\n‒ результаты расширенной диагностики:\r\n̵ протокол ВИК;\r\n̵ протокол геодезического обследования трубопровода;\r\n̵ протокол ультразвуковой толщинометрии стенок элементов трубопроводов;\r\n̵ протокол ультразвуковой толщинометрии сканированием стенок элементов \r\nтрубопроводов;\r\n̵ протокол замеров твердости;\r\n‒ результаты инженерных расчетов:\r\n̵ гидравлического расчета, в том числе расчета прочности трубопровода на \r\nгидроудар;\r\n̵ расчета отбраковочной толщины стенки;\r\n̵ расчета скорости коррозии;\r\n̵ расчёта остаточного ресурса трубопроводов;\r\n‒ анализ результатов диагностики;", "[стр. 6]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n6\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n‒ выводы и рекомендации.", "[стр. 7]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n7\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n2 КРАТКАЯ ХАРАКТЕРИСТИКА ОБЪЕКТА ДИАГНОСТИКИ\r\nОбъектом диагностики, рассматриваемым в Томе № 2 Водовод от УП №1 до пруда \r\n- накопителя, инв.№ 39400183632 является трубопровод, в состав которого входят трубы \r\nдиаметром 426 мм, имеющие внутреннюю футеровку из полиуретана. Краткая \r\nхарактеристика трубопровода приведена в таблице 2.\r\nТаблица 2. Краткая характеристика трубопровода\r\nНаименование предприятия: Талнахская обогатительная фабрика,\r\nЗФ ПАО «ГМК «Норильский никель»\r\nЦех или установка: Цех гидротехнических сооружений и гидротранспорта \r\nТОФ\r\nНаименование трубопровода: Водовод от УП №1 до пруда - накопителя\r\nНазначение: Перекачка воды\r\nГод ввода в эксплуатацию: 2016\r\nНаименование рабочей среды: Оборотная вода\r\nТип изоляции трубопровода: Экструдированный пенополистирол, покрытый \r\nалюминиевой фольгой\r\nРабочее давление, МПа: 1,0 - 1,6\r\nРабочая температура перекачиваемой среды, °С: 0-20\r\nМатериал сталь\r\nДиаметр, мм 426\r\nНоминальная толщина, мм 8\r\nМатериал футеровки полиуретан\r\nТолщина футеровки, мм 10\r\nОбщая протяженность, м 115\r\nКатегория трубопровода: -\r\nРасчетный срок службы трубопровода, лет: 10", "[стр. 8]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n8\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n3 РЕЗУЛЬТАТЫ ПРОВЕДЁННОЙ ДИАГНОСТИКИ\r\n3.1 Документальное обследование\r\nПоиск и анализ технической, эксплуатационной и проектной документации \r\nвыполнен с целью анализа основных параметров, характеризующих работу \r\nтрубопровода, детального ознакомления с конструкцией, особенностями изготовления, \r\nхарактером и конкретными условиями работы. Перечень запрашиваемой и \r\nпредоставленной документации представлен в таблице 3.\r\nТаблица 3. Перечень запрашиваемой и предоставленной документации\r\nНаименование документа Шифр Количество \r\nстраниц\r\nПаспорт на технологические трубопроводы Не предоставлен -\r\nПроектная документация водоотливного трубопровода 3494.2-ИОС 7.3.1 123\r\nПаспорта на запорную арматуру Не предоставлены -\r\nСведения о ремонтных работах на трубопроводах \r\n(текущих, капитальных, планово-предупредительных) Не предоставлены -\r\nАкты о проведенных испытаниях трубопроводов (на \r\nпрочность и плотность, герметичность; неразрушающего \r\nконтроля сварных соединений и других испытаний)\r\nНе предоставлены -\r\nЧертежи технологических трубопроводов Не предоставлены -\r\nДокументация по предыдущим результатам диагностики Не предоставлена -\r\nСведения об использованных материалах ТУ 2258-004-45130869-2013 13\r\nИные документы Инструкция по эксплуатации \r\nтрубопроводов и отводов, \r\nфутерованных полиуретаном \r\nпроизводства ЗАО «СОМЭКС»\r\n8\r\nПо результатам документального обследования выявлено:\r\n1. Отсутствует паспорт трубопровода;\r\n2. Проектная документация предоставлена частично;\r\n3. Отсутствуют паспорта на запорную арматуру;\r\n4. Отсутствуют систематизированные сведения о проведенных ремонтах;\r\n5. Отсутствуют сведения об испытаниях;\r\n6. Техническая диагностика не проводилась.\r\nВ связи с отсутствием (не предоставлением) проектной документации, оценка \r\nсоответствия объекта проектным требованиям выполнена путем анализа требований \r\nнорм проектирования, предъявляемых для данного типа объектов.\r\nТак как исполнительная документация отсутствует (не предоставлена), \r\nнеобходимые и отсутствующие данные были собраны в ходе проведения диагностики, \r\nпутем дополнительных обмерных работ или исследований свойств и характеристик \r\nматериалов элементов сооружения.\r\nПо результатам проведенной технической диагностики получены следующие \r\nданные:\r\n‒ протяженность трубопровода – 115 м;\r\n‒ исполнительная толщина элементов трубопровода представлена в таблице № \r\n4.\r\nТаблица 4. Исполнительная толщина элементов трубопровода\r\nДиаметр, мм Исполнительная толщина, мм\r\n426 6,0; 7,0; 8,0", "[стр. 9]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n9\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n3.2 Основной этап\r\n3.2.1 Визуальный контроль\r\nВизуальный контроль диагностируемого трубопровода выполнен в соответствии с \r\nПрограммой и Регламентом проведения диагностики футерованных трубопроводов \r\nсистемы гидротранспорта Талнахской обогатительной фабрики. \r\nОбщи вид участка трубопровода представлен в Приложении 1.\r\n3.2.2 Экспресс диагностика\r\n3.2.2.1 Акустическая томография\r\nАТ не проводилась в связи с отсутствием условий для проведения контроля – на \r\nмомент диагностики трубопровод был опорожнен.\r\n3.2.2.2 Бесконтактная магнитометрическая диагностика\r\nБМД выполнено в соответствии с Программой проведения диагностики \r\nфутерованных трубопроводов системы гидротранспорта Талнахской обогатительной \r\nфабрики.\r\nВ ходе проведения БМД металла трубопровода аномалии магнитного поля, \r\nсвидетельствующие о наличии зон концентраций напряжений, не обнаружены.\r\nРезультаты БМД трубопровода приведены в Приложении № 3.\r\n3.2.3 Расширенная диагностика\r\n3.2.3.1 Визуальный и измерительный контроль\r\nВИК выполнен в соответствии с Программой и Регламентом проведения \r\nдиагностики футерованных трубопроводов системы гидротранспорта Талнахской \r\nобогатительной фабрики.\r\nПо результатам ВИК трубопровода выявлены следующие дефекты:\r\n‒ Контакт трубопровода с грунтом\r\n‒ Коррозия болтов\r\n‒ Некомплектность болтов на фланцевом соединении\r\n‒ Отсутствие контакта трубы с опорой\r\n‒ Разрушение опоры\r\nРезультаты ВИК приведены в таблице 2 Приложения № 4.\r\n3.2.3.2 Геодезическое обследование трубопровода\r\nГеодезическое обследование трубопровода выполнено в соответствии с \r\nПрограммой проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики.\r\nПо результатам геодезического обследовании участка трубопровода определены \r\nплановые и высотные координаты отдельных секций, составлен высотный план и \r\nопределены места проседания трубопровода.\r\nНа участке «Водовод от УП №1 до пруда - накопителя» рекомендуется \r\nкорректировка высотного положения водовода между секциями 16640-16720.\r\nРезультаты геодезического обследования приведены в Приложении № 5.", "[стр. 10]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n10\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n3.2.3.3 Ультразвуковая толщинометрия стенок элементов\r\nтрубопроводов\r\nУЗТ выполнена в соответствии с Программой и Регламентом проведения \r\nдиагностики футерованных трубопроводов системы гидротранспорта Талнахской \r\nобогатительной фабрики.\r\nПо результатам УЗТ стенки трубопровода минимальная толщина стенки составляет \r\nдля:\r\n‒ прямого участка Ø 426 мм – 5,6 мм.\r\nУтонение стенки трубы не превышает 10%.\r\nРезультаты УЗТ приведены в Приложении № 6.\r\n3.2.3.4 Ультразвуковая толщинометрия сканированием стенок \r\nэлементов трубопроводов\r\nУЗТ/С выполнено в соответствии с Программой и Регламентом проведения \r\nдиагностики футерованных трубопроводов системы гидротранспорта Талнахской \r\nобогатительной фабрики.\r\nВ результате сплошного ультразвукового сканирования была зафиксирована \r\nминимальная толщина 5,0 мм. \r\nРезультаты УЗТ/С приведены в Приложении № 7.\r\n3.2.3.5 Радиографический контроль\r\nРадиографический контроль не проводился в связи с отсутствие мест, подходящих \r\nдля применения данного метода контроля.\r\n3.2.3.6 Проверка механических свойств металла \r\nтрубопроводов\r\nИзмерение твёрдости выполнено в соответствии с Программой и Регламентом \r\nпроведения диагностики футерованных трубопроводов системы гидротранспорта \r\nТалнахской обогатительной фабрики.\r\nИзмеренные значения твёрдости металла стенок трубопроводов находятся в \r\nдопустимых пределах для стали марки 17ГС-1 (100-170 HB в соответствии с \r\nСО 153 34.17.439–2003).\r\nРезультаты измерения твёрдости приведены в Приложении № 9.\r\n3.3 Контрольный этап\r\n3.3.1 Внутритрубная телеинспекция\r\nВнутритрубная телеинспекция не проводилась в связи с отсутствием \r\nподготовленных участков.\r\n3.4 Инженерные расчеты\r\n3.4.1 Гидравлический расчет\r\nРасчет давления воды участка трубопровода выполнен с помощью \r\nгидравлического моделирования в программном комплексе ZuluHydro 10. Средствами ПО \r\nбыл разработан цифровой двойник участка трубопровода и проведен поверочный \r\nгидравлический расчет. Для выполнения гидравлического расчета трубопровод был \r\nусловно разделен на участки. В результате расчета для каждого участка были \r\nопределены подачи и напоры воды в узловых точках.", "[стр. 11]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n11\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРезультаты гидравлического расчета трубопровода представлены в Приложении \r\n11.\r\n3.4.2 Расчет отбраковочной толщины\r\nРасчет отбраковочной толщины стенки трубопровода проведен согласно \r\nГОСТ 32388-2013 «Технологические трубопроводы. Нормы и методы расчета на \r\nпрочность, вибрацию и сейсмические воздействия». Расчет производился в соответствии \r\nс гидравлическим расчетом.\r\nОтбраковочная толщина стенки трубопровода при рабочем давлении и давлении \r\nс учетом гидроудара представлена в таблице 5.\r\nТаблица 5. Отбраковочная толщина стенки трубопровода при рабочем давлении и \r\nдавлении с учетом гидроудара\r\nДиаметр и элемент [Sфmin], мм\r\n[S] при рабочем \r\nдавлении, мм\r\n[S] при давлении, с \r\nучетом гидроудара, мм\r\n426 (труба) 4,4 4,0 4,0\r\nРезультаты расчета отбраковочной толщины приведены в Приложении № 12.\r\n3.4.3 Расчет скорости коррозии\r\nРасчет скорости коррозии проведен согласно «Методики оценки остаточного \r\nресурса технологических трубопроводов» (утв. Министерством топлива и энергетики \r\nРоссийской Федерации 17.07.96).\r\nМаксимальная рассчитанная равномерная скорость коррозии – 0,056 мм в год на \r\nсекции 16680.\r\nРасчеты и результаты анализа скорости коррозии приведены в Приложении № 13.\r\n3.4.4 Расчет остаточного ресурса трубопровода\r\nРасчет остаточного ресурса трубопровода проведен согласно п.5.3 «Методики \r\nоценки остаточного ресурса технологических трубопроводов» (утв. Министерством \r\nтоплива и энергетики Российской Федерации 17.07.96).\r\nОстаточный ресурс всех секции – более 8 лет.\r\nРезультаты расчёта остаточного ресурса трубопровода приведены в Приложении \r\n№ 13.\r\n3.5 Анализ результатов диагностики\r\nВ ходе диагностики водовода от УП №1 до пруда - накопителя были использованы \r\nследующие методы контроля:\r\n‒ визуальный и измерительный контроль (ВИК);\r\n‒ геодезическое обследование (ГО);\r\n‒ акустическая томография (АТ);\r\n‒ ультразвуковая толщинометрия (УЗТ);\r\n‒ бесконтактная магнитометрическая диагностика (БМД);\r\n‒ измерение твердости.\r\nВыполнен анализ результатов проведенного документального обследования, \r\nинструментального обследования, инженерных расчетов. В результате анализа \r\nсформирован перечень дефектов, ранжированных по степени критичности. Описание", "[стр. 12]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n12\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nкритериев ранжирования дефектов представлено в таблице 6, результаты ранжирования \r\nвыявленных дефектов – в таблице 7.\r\nТаблица 6. Ранжирование дефектов по степени влияния на безопасность эксплуатации \r\nтрубопровода\r\nРанг \r\nдефекта\r\nНаименование \r\nдефекта Описание дефекта\r\nI\r\nКритический \r\nдефект\r\nДефект трубопровода, требующий незамедлительного устранения. \r\nЭксплуатация трубопровода с критическими дефектами недопустима.\r\nII\r\nДокритический \r\nдефект\r\nДефект, требующий устранения при проведении плановых \r\nпредупредительных ремонтов.\r\nЭксплуатация трубопровода с докритическими дефектами возможна с \r\nосуществлением периодического контроля за параметрами дефекта до \r\nследующего планового ремонта.\r\nIII\r\nНезначительный \r\nдефект\r\nДефект, не оказывающий существенного влияния на надёжность и \r\nдолговечность эксплуатации трубопровода.\r\nПериодический контроль за параметрами дефекта осуществляется при \r\nпроведении очередной диагностики.\r\nТаблица 7. Перечень выявленных дефектов\r\n№ \r\nп/п Местонахождение дефекта Описание дефекта Ранг \r\nдефекта\r\n1 Контакт трубопровода с грунтом Дефекты № 5,7 протокол ВИК II\r\n2 Разрушение опоры Дефекты № 1,2 протокол ВИК II\r\n3\r\nОтсутствие контакта трубы с \r\nопорой Дефект № 3 протокол ВИК II\r\n4\r\nНекомплектность болтов на \r\nфланцевом соединении Дефект № 8 протокол ВИК II\r\n5\r\nОбразование застойной зоны более \r\nполовины диаметра трубы\r\nСекция №16680 протокол геодезического \r\nобследования II\r\n6 Коррозия болтов и/или фланцев Дефекты №1,4,6,8 протокол ВИК III\r\n3.6 Выводы и рекомендации\r\nПо результатам анализа технической документации составлены рекомендации, \r\nнаправленные на обеспечение дальнейшей безопасной эксплуатации трубопроводов:\r\n‒ восстановить техническую документацию (разработать паспорта на \r\nтрубопровод и запорную арматуру);\r\n‒ вести учет аварий и инцидентов на трубопроводах;\r\n‒ проводить испытания на прочность, плотность и герметичность.\r\nПо результатам диагностики составлены рекомендации, направленные на \r\nобеспечение дальнейшей безопасной эксплуатации трубопроводов:\r\n‒ проверить комплектность болтов на фланцевых соединениях (дефект №8 \r\nПриложение №4);\r\n‒ восстановить опорную систему трубопровода (дефекты № 1,2,3 Приложение \r\n№4);\r\n‒ ликвидировать контакт трубопровода с грунтом (дефекты № 5,7 Приложение \r\n№ 4);\r\n‒ провести работы по выравниванию высотного положения трубопровода для \r\nликвидации застойных зон (Приложение №5).", "[стр. 13]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n13\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nВ связи с отсутствием сведений о проведенных обследованиях, ремонтах, авариях \r\nна трубопроводе, рекомендуется выполнить повторную диагностику через 2 года для \r\nоперативного контроля за изменением состояния объекта, в соответствии с \r\nГОСТ 31937-2024 «Здания и сооружения. Правила диагностирования и мониторинга \r\nтехнического состояния».\r\nПри своевременном планировании и проведении периодической диагностики, \r\nвыявлении дефектов и последующем их устранении, срок безопасной эксплуатации \r\nтрубопровода существенно увеличивается, а накопленные статистические данные \r\nпозволяют определить на эксплуатирующихся объектах вероятность возникновения \r\nинцидентов либо аварий и заблаговременно предотвратить их возникновение.\r\n3.6.1 Мероприятия, направленные на обеспечение дальнейшей безопасной \r\nэксплуатации трубопроводов\r\nДля обеспечения дальнейшей безопасной эксплуатации трубопровода Водовод от \r\nУП №1 до пруда - накопителя, инв.№ 39400183632 составлены рекомендации, указанные \r\nв таблице 8 и ведомость объемов работ по их устранению.", "[стр. 14]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 14 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nТаблица 8. Ведомость объемов работ по устранению дефектов для обеспечения дальнейшей безопасной эксплуатации \r\nфутерованного трубопроводов системы гидротранспорта Талнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский никель» \r\n- Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632\r\n№ \r\nп/п\r\n№ \r\nТома\r\nНаименование \r\nтрубопровода\r\nДиаметр \r\nтрубопровода, мм № дефекта Описание дефекта Работы по устранению дефекта\r\n1\r\n5\r\nТрубопровод \r\nоборотной воды №1 \r\nДу 426 мм участок \r\n«Водовод от УП №1 \r\nдо пруда￾накопителя», \r\nинв.№ 39400183632\r\n426\r\nДефекты № 5,7 \r\nпротокол ВИК\r\nКонтакт трубопровода с \r\nгрунтом\r\n1. Удалить грунт, прилегающий к трубопроводу \r\nс перемещением в отвал (ручная работа) 4 м3.\r\n2. ВИК и УЗ толщинометрия участков \r\nтрубопровода, освобождённых от грунта Ø 426 \r\nмм, L=11,0 п.м.\r\n2\r\nДефекты № 1,2 \r\nпротокол ВИК Разрушение опоры 1.Восстановить опоры. L=11,0 м.\r\n2. Монтировать трубопроводы на опоры.\r\n3\r\nДефект № 3 протокол \r\nВИК\r\nОтсутствие контакта \r\nтрубы с опорой\r\n1.Восстановить опоры. L=5,5,0 м.\r\n2. Монтировать трубопроводы на опоры.\r\n4\r\nДефект № 8 протокол \r\nВИК\r\nНекомплектность болтов \r\nна фланцевом \r\nсоединении\r\n1.Установка новых болтовых соединений\r\n5\r\nСекция №16680 \r\nпротокол \r\nгеодезического \r\nобследования\r\nОбразование застойной \r\nзоны более половины \r\nдиаметра трубы\r\n1.Корректировка высотного положения \r\nтрубопровода", "[стр. 15]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n15\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЯ", "[стр. 16]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 16 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 1\r\nОБЩИЙ ВИД УЧАСТКА ТРУБОПРОВОДА\r\nРисунок 1. Общий вид трубопровода", "[стр. 17]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 17 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nТаблица 1. Перечень точек, отмеченных на схеме\r\nНаименование точки Номера секций Описание\r\nт15 16600 Начало участка «Водовод от УП №1 до пруда-накопителя»\r\nд10 16640-16680 участок под дорогой\r\nд11 16760-16770 участок под дорогой\r\nт16 16780 Конец участка «Водовод от УП №1 до пруда-накопителя»", "[стр. 18]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 18 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nРисунок 2. Общий вид трубопровода", "[стр. 19]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n19\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 3\r\nОбщество с ограниченной ответственностью\r\n«Цветметэкспертиза»\r\nЛаборатория неразрушающего контроля и диагностики\r\nСвидетельство об аттестации № АЦЛНК-36-00005 (действительно до 05.07.2026)\r\nПРОТОКОЛ\r\nБЕСКОНТАКТНОЙ МАГНИТОМЕТРИЧЕСКОЙ ДИАГНОСТИКИ\r\n06.10.2025 № 2-25-167-01-ТО-6\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК \r\n«Норильский никель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nБМД металла выполнена в соответствии с документами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики.\r\n‒ Федеральные нормы и правила в области промышленной безопасности \r\n«Основные требования к проведению неразрушающего контроля технических устройств, \r\nзданий и сооружений на опасных производственных объектах» (утв. приказом \r\nФедеральной службы по экологическому, технологическому и атомному надзору от \r\n01.12.2020 №478);\r\n‒ РД 102-008-2002 «Инструкция по диагностике технического состояния \r\nтрубопроводов бесконтактным магнитометрическим методом»;\r\n‒ ГОСТ Р ИСО 24497 - 2 - 2009 «Контроль неразрушающий. Метод магнитной \r\nпамяти металла. Часть 2. Общие требования».\r\nОбъём контроля\r\nБМД выполнен в объеме, предусмотренном Программой проведения диагностики \r\nфутерованных трубопроводов системы гидротранспорта.\r\nБМД проводится в отношении участков, пригодных для локализации и \r\nподтверждения мест дефектов, выявленных при помощи АТ.\r\nСхема расположения мест проведения измерений приведена на рисунке 2.\r\nПараметры контроля\r\nУсловия контроля:\r\n‒ освещенность не менее 500 Лк;\r\n‒ температура окружающей среды не превышает установленных паспортом \r\nдопустимых параметров эксплуатации приборов.", "[стр. 20]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n20\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nСредства контроля\r\nТаблица 1. Средства контроля\r\nНаименование прибора Назначение \r\nприбора Заводской номер Свидетельство о поверке\r\nПрибор магнитометрический \r\nдля определения \r\nконцентрации напряжений ИКН\r\nИзмерение \r\nконцентрации \r\nнапряжений\r\n5М-32-017\r\nот 03.06.2025 \r\n№ С-ДДЭ/03-06-2025/437665939 \r\n(действительно до 02.06.2026)\r\nЛюксметр Testо-540\r\nИзмерение \r\nосвещенности \r\nрабочей зоны\r\n39105292/0920\r\nот 15.01.2025\r\n№ С-ВЯ/15-01-2025/402423299 \r\n(действительно до 14.01.2026)\r\nПирометр инфракрасный \r\nRGK PL-12\r\nИзмерение \r\nтемпературы\r\n23052127\r\nот 03.06.2025\r\n№ С-ДДЭ/03-06-2025/437665937\r\nдействительно до 02.06.2026)\r\nРезультаты контроля\r\n1. Участок между секциями 16600-16640.\r\nКонтроль участка с выявленными аномалиями по результатам АТ. Протяженность \r\nучастка – 22,0 м. \r\nРисунок 1. Магнитограмма распределения напряженности магнитного поля и её \r\nградиента. Участок между секциями 16600-16640\r\nПо результатам диагностики зоны концентрации напряжений не выявлены.", "[стр. 21]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n21\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nВывод\r\nВ ходе проведения БМД металла трубопровода аномалии магнитного поля, \r\nсвидетельствующие о наличии зон концентраций напряжений, не обнаружены. \r\nПротокол подготовил, контроль выполнил:\r\nВедущий инженер,\r\nспециалист по БМД,\r\nсертификат от 21.02.2025\r\n№ БМД-474-2685\r\n(действителен до 20.02.2028) Д.О. Нескашин", "[стр. 22]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 22 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nРисунок 2. Схема проведения БМД", "[стр. 23]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 23 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nРисунок 3. Схема контроля БМД", "[стр. 24]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n24\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 4\r\nОбщество с ограниченной ответственностью\r\n«Цветметэкспертиза»\r\nЛаборатория неразрушающего контроля и диагностики\r\nСвидетельство об аттестации № АЦЛНК-36-00005 (действительно до 05.07.2026)\r\nПРОТОКОЛ\r\nВИЗУАЛЬНОГО И ИЗМЕРИТЕЛЬНОГО КОНТРОЛЯ\r\n06.10.2025 № 2-25-167-01-ТО-1\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК «Норильский \r\nникель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nВИК проведён в соответствии с документами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики.\r\n‒ Федеральные нормы и правила в области промышленной безопасности \r\n«Основные требования к проведению неразрушающего контроля технических устройств, \r\nзданий и сооружений на опасных производственных объектах» (утв. приказом \r\nФедеральной службы по экологическому, технологическому и атомному надзору от \r\n01.12.2020 №478);\r\n‒ Федеральные нормы и правила в области промышленной безопасности \"Правила \r\nбезопасной эксплуатации технологических трубопроводов» (утв. приказом Ростехнадзора \r\nот 21.12.2021 № 444);\r\n‒ Руководство по безопасности «Методические рекомендации о порядке \r\nпроведения визуального и измерительного контроля» (утв. приказом Федеральной \r\nслужбы по экологическому, технологическому и атомному надзору от 16.01.2024 № 8);\r\n‒ Методика оценки остаточного ресурса технологических трубопроводов (утв. \r\nМинистерством топлива и энергетики Российской Федерации 17.07.96);\r\n‒ ГОСТ 16037-80 «Соединения сварные стальных трубопроводов. Основные типы, \r\nконструктивные элементы и размеры».\r\nОбъём контроля\r\nПроведён контроль участка трубопровода – Водовод от УП №1 до пруда -\r\nнакопителя, инв.№ 39400183632, общая протяжённость 115 м.\r\nПроводится визуальный контроль элементов трубопровода снаружи в объеме 100% \r\nдоступных мест.\r\nПри наружном осмотре элементов трубопровода проверяется:\r\n‒ соответствие трассировки и конструкции трубопроводов монтажно-сборочными \r\nчертежами, исполнительным схемам или проекту;\r\n‒ состояния изоляции и антикоррозионного покрытия, защитных кожухов \r\nтрубопровода;\r\n‒ отсутствие или наличие дефектов трассировки трубопроводов: защемлений, \r\nпрогибов, провисаний;", "[стр. 25]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n25\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n‒ состояние элементов трубопроводов прямых участков труб, отводов (гибов), \r\nпереходов, тройников, врезок, заглушек, компенсирующих устройств;\r\n‒ -расположение и исправность дренажей и воздушников (при их наличии);\r\n‒ состояние опорно-подвесной системы трубопроводов на предмет исправности \r\nопор, подвесок и пружинных блоков, смещений опор с опорных поверхностей, перекос \r\nопор;\r\n‒ состояние муфтовых и фланцевых соединений, в том числе полнота его \r\nукомплектованности и правильности установки крепёжных деталей (шпилек, болтов, гаек) \r\nособенно в районе расположения неподвижных опор;\r\n‒ состояние запорно-регулирующей арматуры (задвижек, вентилей, клапанов \r\nобратных) фланцевых соединений, крышки и уплотнения шпинделя, наружных \r\nповерхностей запорной арматуры;\r\n‒ нарушений герметичности разъемных соединений и сальниковых уплотнений \r\nзапорной арматуры (следов пропуска рабочей среды на основном металле, сварных швах \r\nи в уплотнительных соединениях);\r\n‒ наличие коррозионных дефектов (равномерная, неравномерная коррозия, \r\nпиттинг и другие дефекты).\r\nПри наличии возможности, осуществляется внутренний осмотр элементов \r\nтрубопровода через демонтированные разъемные соединения или в местах \r\nдемонтированной арматуры.\r\nПроизводится измерительный контроль с определением размеров обнаруженных \r\nдефектов в процессе наружного осмотра (поры, свищи, подрезы, раковины, вмятины, \r\nвыпучины и др.). Их форма, расположение и размеры указываются в акте визуального и \r\nизмерительного контроля.\r\nПараметры контроля\r\nУсловия контроля:\r\n‒ освещенность не менее 500 Лк,\r\n‒ шероховатость зачищенных под контроль поверхностей не более Rа12,5;\r\n‒ температура окружающей среды не превышает установленных паспортом \r\nдопустимых параметров эксплуатации приборов.\r\nСредства контроля\r\nИспользованные приборы и инструменты приведены в таблице 1.\r\nТаблица 1. Средства контроля\r\nНаименование прибора Назначение прибора Заводской номер Свидетельство о поверке\r\nКомплект для ВИК-1 \r\n«Эксперт»\r\nИзмерения контролируемых \r\nпараметров труб, контроля \r\nкачества сборки стыков труб, а \r\nтакже для измерения параметров \r\nсварного шва при его контроле\r\nБ0211-19\r\nСертификат о \r\nкалибровке от 26.12.2024\r\n№ В.КЮС-7334-24 \r\n(действительно до \r\n25.12.2025)\r\nЛюксметр Testо-540 Измерение освещенности рабочей \r\nзоны\r\n39105292/0920\r\nот 15.01.2025\r\n№ С-ВЯ/15-01-\r\n2025/402423299 \r\n(действительно до \r\n14.01.2026)", "[стр. 26]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n26\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nНаименование прибора Назначение прибора Заводской номер Свидетельство о поверке\r\nПирометр \r\nинфракрасный \r\nRGK PL-12\r\nИзмерение температуры 23052127\r\nот 03.06.2025\r\n№ С-ДДЭ/03-06-\r\n2025/437665937\r\nдействительно до \r\n02.06.2026)\r\nДальномер лазерный \r\nRGK D80 Измерение расстояний 896448565\r\nот 28.12.2024\r\n№ С-ГХШ/27-12-\r\n2024/399704463 \r\n(действительно до \r\n26.12.2025)\r\nНабор образцов \r\nшероховатости\r\nОпределение шероховатости \r\nповерхности\r\n0012\r\nСертификат о \r\nкалибровке от 09.02.2024\r\n№ Ш.КЮС-510-24 \r\n(действительно до \r\n08.02.2026)\r\nФотоаппарат OLYMPUSS \r\nTough TG-7\r\nФотофиксация объекта BJPA66049 Поверке не подлежит", "[стр. 27]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 27 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nРезультаты контроля\r\nРезультаты ВИК приведены в таблице 2.\r\nТаблица 2. Результаты ВИК\r\n№ \r\nп/п\r\nНомер \r\nсоединения/секции Описание дефекта Фотофиксация\r\n1. 16600 Коррозия болтов", "[стр. 28]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 28 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\n№ \r\nп/п\r\nНомер \r\nсоединения/секции Описание дефекта Фотофиксация\r\nРазрушение опоры", "[стр. 29]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 29 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\n№ \r\nп/п\r\nНомер \r\nсоединения/секции Описание дефекта Фотофиксация\r\n2. 16610 Разрушение опоры\r\n3. 16620 Отсутствие контакта трубы с опорой", "[стр. 30]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 30 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\n№ \r\nп/п\r\nНомер \r\nсоединения/секции Описание дефекта Фотофиксация\r\n4. 16680 Коррозия болтов\r\n5. 16740 Контакт трубопровода с грунтом", "[стр. 31]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 31 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\n№ \r\nп/п\r\nНомер \r\nсоединения/секции Описание дефекта Фотофиксация\r\n6. 16760 Коррозия болтов\r\n7. 16770 Контакт трубопровода с грунтом", "[стр. 32]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 32 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\n№ \r\nп/п\r\nНомер \r\nсоединения/секции Описание дефекта Фотофиксация\r\n8. 16780\r\nКоррозия болтов\r\nНекомплектность болтов на фланцевом \r\nсоединении", "[стр. 33]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 33 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nРисунок 1. Места дефектов, обнаруженных при ВИК", "[стр. 34]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n34\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nВывод\r\nПо результатам ВИК участка трубопровода выявлены следующие дефекты:\r\n контакт трубопровода с грунтом;\r\n коррозия болтов;\r\n некомплектность болтов на фланцевом соединении;\r\n отсутствие контакта трубы с опорой;\r\n разрушение опоры.\r\nПротокол подготовил, контроль выполнил: \r\nВедущий инженер,\r\nспециалист 2-го уровня по ВИК,\r\nудостоверение от 28.02.2025\r\n№ 0039-34502\r\n(действительно до 28.02.2028) Д.О. Нескашин", "[стр. 35]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n35\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 5\r\nОбщество с ограниченной ответственностью\r\n«Уральский центр промышленной безопасности»\r\nЛаборатория неразрушающего контроля и диагностики\r\nСвидетельство об аттестации № ЛНК-075А0050 действительно до 20.09.2027;\r\nСвидетельство об аккредитации № ИЛ/ЛНК-00737 действительно до 23.11.2026.\r\nПРОТОКОЛ\r\nГЕОДЕЗИЧЕСКОГО ОБСЛЕДОВАНИЯ ТРУБОПРОВОДА\r\n06.10.2025 № 2-25-167-01-ТО-4\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК \r\n«Норильский никель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nГеодезическое обследование трубопровода проведено в соответствии с \r\nдокументами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики.\r\n‒ Федеральные нормы и правила в области промышленной безопасности \r\n«Основные требования к проведению неразрушающего контроля технических устройств, \r\nзданий и сооружений на опасных производственных объектах» (утв. приказом \r\nФедеральной службы по экологическому, технологическому и атомному надзору от \r\n01.12.2020 №478);\r\n‒ ГОСТ Р 51872-2024 «Документация исполнительная геодезическая»;\r\n‒ СП 126.13330.2017 — «Геодезические работы в строительстве».\r\nОбъём контроля\r\nГеодезическое обследование трубопровода выполнено в объеме, \r\nпредусмотренном Программой проведения диагностики футерованных трубопроводов \r\nсистемы гидротранспорта Талнахской обогатительной фабрики.\r\nПроводится определение геодезический координат начала каждой секции \r\nтрубопровода.\r\nПараметры контроля\r\nУсловия контроля:\r\n‒ температура окружающей среды не превышает установленных паспортом \r\nдопустимых параметров эксплуатации приборов.", "[стр. 36]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n36\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nСредства контроля:\r\nТаблица 1. Средства контроля\r\nНаименование \r\nприбора Назначение прибора Заводской \r\nномер\r\nСвидетельство о \r\nповерке\r\nПолевой контроллер \r\nPrinСe HCE600\r\nУправление приемниками \r\nГНСС 6405303921 -\r\nПриемник ГНСС Prince \r\ni20AR Определение \r\nместоположения при помощи \r\nспутниковых систем\r\n4071303 -\r\nПриемник ГНСС\r\nPrince i90 IMU 3517659 -\r\nПирометр \r\nинфракрасный \r\nRGK PL-12\r\nИзмерение температуры 23052127\r\nот 03.06.2025\r\n№ С-ДДЭ/03-06-\r\n2025/437665937 \r\nдействительно до \r\n02.06.2026)\r\nРезультаты контроля\r\nВ ходе проведения обследования водовода от УП №1 до пруда - накопителя для \r\n16 секций были определены плановые и высотные координаты начала секций. Секциям \r\nбыли присвоены номера от 16600 до 16780 с шагом в 10. Результаты обследования \r\nпредставлены в таблице 2. \r\nНа основе данных о высотном положении секций проведен анализ высотного \r\nположения с определены места провисания трубопровода на величину более половины \r\nдиаметра трубопровода. Высотный профиль участка трубопровода представлен на \r\nрисунках 1-3. Сведения о самых низких точках представлены в таблице 3.\r\nТаблица 2. Результаты определения плановых и выссотных координат секций \r\nтрубопровода\r\nНомер \r\nсекции\r\nКоординаты в Кайерканской СК\r\nПлановые координаты в WSG84\r\nX Y h\r\nс16600 28605.989 27171.402 64.688 69.503267571, 88.350882083\r\nс16610 28600.953 27168.500 64.587 69.503223015, 88.350805029\r\nс16620 28596.213 27165.785 64.538 69.503181068, 88.350732925\r\nс16630 28591.153 27163.346 64.485 69.503136201, 88.350667700\r\nс16640 28586.367 27160.938 64.385 69.503093795, 88.350603426\r\nс16680 28568.825 27151.896 63.865 69.502938373, 88.350362312\r\nс16690 28564.248 27149.512 63.893 69.502897830, 88.350298755\r\nс16700 28560.735 27147.638 63.927 69.502866719, 88.350248862\r\nс16710 28556.711 27145.481 63.932 69.502831083, 88.350191437\r\nс16720 28555.206 27144.729 64.010 69.502817745, 88.350171350\r\nс16730 28554.605 27144.667 63.953 69.502812364, 88.350169445\r\nс16740 28550.381 27145.459 63.777 69.502774358, 88.350187308", "[стр. 37]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n37\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nНомер \r\nсекции\r\nКоординаты в Кайерканской СК\r\nПлановые координаты в WSG84\r\nX Y h\r\nс16750 28545.029 27146.498 63.666 69.502726192, 88.350210854\r\nс16760 28539.992 27147.585 63.574 69.502680834, 88.350235806\r\nс16770 28529.471 27149.969 63.527 69.502586082, 88.350290843\r\nс16780 28524.911 27151.002 63.521 69.502545010, 88.350314699\r\nРисунок 1. Высотный профиль участка водовода\r\nТаблица 3. Координаты точек с наиболее низкими отметками:\r\nНомер соединения Высотная отметка, м Координаты в WSG84\r\n16680 63,865 69.502938373, 88.350362312\r\nВывод\r\nПо результатам геодезического обследовании участка трубопровода определены \r\nплановые и высотные координаты отдельных секций, составлен высотный план и \r\nопределены места проседания трубопровода.\r\nНа участке водовода от УП №1 до пруда-накопителя рекомендуется корректировка \r\nвысотного положения водовода между секциями 16640-16720.\r\nПротокол подготовил, контроль выполнил:\r\nИнженер 1 категории,\r\nудостоверение №662415680622 от 29.04.2022 Коротаев А.С.\r\n63\r\n63,4\r\n63,8\r\n64,2\r\n64,6\r\n65\r\nс16600 с16610 с16620 с16630 с16640 с16680 с16690 с16700 с16710 с16720 с16730 с16740 с16750 с16760 с16770 с16780\r\nВысотный профиль водовода С16600 (УП №1)-С16780 \r\n(водосброс)", "[стр. 38]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n38\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 6\r\nОбщество с ограниченной ответственностью\r\n«Цветметэкспертиза»\r\nЛаборатория неразрушающего контроля и диагностики\r\nСвидетельство об аттестации № АЦЛНК-36-00005 (действительно до 05.07.2026)\r\nПРОТОКОЛ\r\nУЛЬТРАЗВУКОВОЙ ТОЛЩИНОМЕТРИИ\r\n06.10.2025 № 2-25-167-01-ТО-3\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК \r\n«Норильский никель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nУЗТ трубопровода проведена в соответствии с документами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики.\r\n‒ Федеральные нормы и правила в области промышленной безопасности \r\n«Основные требования к проведению неразрушающего контроля технических устройств, \r\nзданий и сооружений на опасных производственных объектах» (утв. приказом \r\nФедеральной службы по экологическому, технологическому и атомному надзору от \r\n01.12.2020 №478);\r\n‒ ГОСТ Р ИСО 16809-2015 «Контроль неразрушающий. Контроль ультразвуковой. \r\nИзмерение толщины»;\r\n‒ Методика оценки остаточного ресурса технологических трубопроводов \r\n(утв. Министерством топлива и энергетики Российской Федерации 17.07.96).\r\nОбъём контроля\r\nУЗТ стенки трубопровода выполнен в объеме, предусмотренном проведения \r\nПрограммой диагностики футерованных трубопроводов системы гидротранспорта\r\nТалнахской обогатительной фабрики.\r\nПроводится контроль толщины трубопровода и его элементов (отводов (гибов), \r\nпереходов, тройников, врезок, заглушек, компенсаторов) в следующем объеме:\r\n‒ на каждой доступной секции трубопровода, на переходах – не менее чем в двух \r\nсечениях;\r\n‒ на каждом доступном отводе, тройнике – не менее чем в трех сечениях;\r\n‒ в зонах критических дефектов по результатам АТ не менее чем в двух сечениях.\r\nВ каждом сечении выполняется измерение толщины в 4 точках, расположенных на \r\n0\r\n0\r\n, 900\r\n, 1800 и 2700\r\n.\r\nСхема измерений толщины трубопровода в сечениях приведена на рисунке 1.", "[стр. 39]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n39\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРисунок 1. Схема измерений толщины трубопровода \r\nИзмерение толщины футеровки проводилось в доступных местах – на \r\nдемонтированных секциях трубопровода.\r\nПараметры контроля\r\nУсловия контроля:\r\n‒ освещенность не менее 500 Лк;\r\n‒ шероховатость зачищенных под контроль участков основного металла не более \r\nRa 6,3;\r\n‒ температура окружающей среды не превышает установленных паспортом \r\nдопустимых параметров эксплуатации приборов.", "[стр. 40]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n40\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nСредства контроля:\r\nТаблица 1. Средства контроля\r\nНаименование \r\nприбора Назначение прибора Заводской \r\nномер\r\nСвидетельство о \r\nповерке\r\nТолщиномер \r\nультразвуковой DM5E\r\nОпределение фактической\r\nтолщины стенки\r\n1504082\r\nот 02.06.2025\r\n№ С-ГХШ/02-06-\r\n2025/436906583 \r\n(действительно до \r\n01.06.2026)\r\nОбразец ступенчатый\r\nСОП 4-16 mm\r\nМатериал Ст20. Настройка \r\nпараметров контроля \r\nприборов. \r\nН=4,6,8,10,12,14,16мм\r\n2018/12\r\nСертификат о \r\nкалибровке от \r\n29.12.2023 \r\n№ С.КЮС-6275-23 \r\n(действительно до \r\n28.12.2025)\r\nДефектоскоп \r\nультразвуковой \r\nMASTER A1212 Измерение толщины \r\nфутеровки\r\n4143030\r\nот 27.12.2024\r\n№ С-ГХШ/27-12-\r\n2024/399704467 \r\n(действительно до \r\n26.12.2025)\r\nПЭП ZT-12 2МГц \r\n(прямой) 6592\r\nГель для \r\nультразвукового \r\nконтроля\r\nОбеспечение контакта между \r\nультразвуковым \r\nпреобразователем и \r\nконтролируемой \r\nповерхностью\r\nб/н -\r\nОбразец V2/25 Настройка глубиномера \r\nдефектоскопа М 0783\r\nСертификат о \r\nкалибровке от \r\n26.12.2024 № К.КЮС￾7374-24 (действителен \r\nдо 25.12.2027)\r\nЛюксметр Testо-540 Измерение освещенности \r\nрабочей зоны 39105292/0920\r\nот 15.01.2025\r\n№ С-ВЯ/15-01-\r\n2025/402423299 \r\n(действительно до \r\n14.01.2026)\r\nПирометр \r\nинфракрасный \r\nRGK PL-12\r\nИзмерение температуры 23052127\r\nот 03.06.2025\r\n№ С-ДДЭ/03-06-\r\n2025/437665937 \r\nдействительно до \r\n02.06.2026)\r\nНабор образцов \r\nшероховатости\r\nОпределение шероховатости \r\nповерхности\r\n0012\r\nСертификат о \r\nкалибровке от \r\n09.02.2024\r\n№ Ш.КЮС-510-24 \r\n(действительно до \r\n08.02.2026)\r\n* при использовании толщиномера DM5E, неопределённость измерений составляет от ±0,22 мм до \r\n±0,36 мм, в соответствии с методикой оценки неопределенности измерений", "[стр. 41]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n41\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРезультаты контроля\r\nТаблица 2. Результаты измерений толщины элементов трубопровода № секции Тип секции Номинальная толщина, мм\r\nЗамеры толщины стенки, мм\r\nМиним. толщина, мм\r\nОтбраковочная \r\nтолщина стенки, мм\r\nУтонение, %\r\nсечение 1 сечение 2 сечение 3\r\n0° 90° 180° 270° 0° 90° 180° 270° 0° 90° 180° 270°\r\n16600 труба 7,0 6,7 6,8 7 7 6,8 6,9 6,8 6,8 6,7 4,0 4,3%\r\n16630 труба 6,0 5,6 5,7 5,8 5,8 5,6 5,7 5,7 5,6 5,6 4,0 6,7%\r\n16640 труба 6,0 5,8 5,7 5,8 5,7 5,7 5,9 5,8 5,9 5,7 4,0 5,0%\r\n16670 труба 7,0 7 6,8 6,9 6,9 6,9 6,8 6,8 7 6,8 4,0 2,9%\r\n16680 труба 7,0 6,7 6,6 6,5 6,5 6,7 6,8 6,7 6,6 6,5 4,0 7,1%\r\n16700 труба 7,0 6,9 6,9 7 6,9 6,8 6,9 7 7 6,8 4,0 2,9%\r\n16750 труба 6,0 5,8 6 6 5,9 5,8 5,9 5,9 5,8 5,8 4,0 3,3%\r\n16760 труба 6,0 5,7 5,7 5,9 5,8 5,8 5,9 5,9 6 5,7 4,0 5,0%\r\n16770 труба 6,0 6,1 5,8 5,9 5,9 5,8 5,9 5,7 5,7 5,7 4,0 5,0%\r\n16780 труба 8,0 8,2 8,2 8,3 8,2 8,1 8,1 8,2 8,2 8,1 4,0 0,0%\r\nВывод\r\nПо результатам УЗТ трубопровода минимальная толщина стенки составляет для:\r\n‒ прямого участка Ø 426 мм – 5,0 мм;\r\nУтонение стенки трубы не превышает 10%.\r\nПротокол подготовил, контроль выполнил:\r\nВедущий инженер,\r\nспециалист 2-го уровня по УК,\r\nудостоверение от 28.02.2025\r\n№ 0039-34502\r\n(действительно до 28.02.2028) Д.О. Нескашин", "[стр. 42]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n42\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРисунок 2. Места контроля толщины стенки трубопровода", "[стр. 43]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n43\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 7 \r\nОбщество с ограниченной ответственностью\r\n«Цветметэкспертиза»\r\nЛаборатория неразрушающего контроля и диагностики\r\nСвидетельство об аттестации № АЦЛНК-36-00005 (действительно до 05.07.2026)\r\nПРОТОКОЛ\r\nУЛЬТРАЗВУКОВОЙ ТОЛЩИНОМЕТРИИ СКАНИРОВАНИЕМ\r\n06.10.2025 № 2-25-167-01-ТО-8\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК \r\n«Норильский никель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nУЗТ/С трубопровода проведена в соответствии с документами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики;\r\n‒ Федеральные нормы и правила в области промышленной безопасности \r\n«Основные требования к проведению неразрушающего контроля технических устройств, \r\nзданий и сооружений на опасных производственных объектах» (утв. приказом \r\nФедеральной службы по экологическому, технологическому и атомному надзору от \r\n01.12.2020 №478);\r\n‒ ГОСТ Р ИСО 16809-2015 «Контроль неразрушающий. Контроль ультразвуковой. \r\nИзмерение толщины»;\r\n‒ Методика оценки остаточного ресурса технологических трубопроводов \r\n(утв. Министерством топлива и энергетики Российской Федерации 17.07.96).\r\nОбъём контроля\r\nУЗТ/С стенки трубопровода выполнен в объеме, предусмотренном Программой \r\nпроведения диагностики футерованных трубопроводов системы гидротранспорта \r\nТалнахской обогатительной фабрики.\r\nПроводится контроль толщины трубопровода методом сплошного сканирования на \r\nучастках трубопровода, которые выявлены в результате УЗТ с утонением более 50%. \r\nСхема расположения мест проведения измерений приведена на рисунке 2.\r\nПараметры контроля\r\nУсловия контроля:\r\n‒ освещенность не менее 500 Лк;\r\n‒ шероховатость зачищенных под контроль участков основного металла не более \r\nRa 6,3;\r\n‒ температура окружающей среды не превышает установленных паспортом \r\nдопустимых параметров эксплуатации приборов.", "[стр. 44]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n44\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nСредства контроля:\r\nТаблица 1. Средства контроля\r\nНаименование прибора Назначение прибора Заводской \r\nномер\r\nСвидетельство о поверке\r\nДефектоскоп \r\nультразвуковой УИУ \r\nСканер «Скаруч»\r\nСплошное \r\nсканирование \r\nстенки \r\nтрубопровода\r\n1643\r\nот 26.12.2024\r\n№ С-ГХШ/26-12-\r\n2024/399480278 \r\n(действительно до \r\n25.12.2025)\r\nГель для ультразвукового \r\nконтроля\r\nОбеспечение \r\nконтакта между \r\nультразвуковым \r\nпреобразователем и \r\nконтролируемой \r\nповерхностью\r\nб/н -\r\nЛюксметр Testо-540\r\nИзмерение \r\nосвещенности \r\nрабочей зоны\r\n39105292/0920\r\nот 15.01.2025\r\n№ С-ВЯ/15-01-\r\n2025/402423299 \r\n(действительно до \r\n14.01.2026)\r\nПирометр инфракрасный \r\nRGK PL-12\r\nИзмерение \r\nтемпературы\r\n23052127\r\nот 03.06.2025\r\n№ С-ДДЭ/03-06-\r\n2025/437665937 \r\nдействительно до \r\n02.06.2026)\r\nНабор образцов \r\nшероховатости\r\nОпределение \r\nшероховатости \r\nповерхности\r\n0012\r\nСертификат о калибровке \r\nот 09.02.2024\r\n№ Ш.КЮС-510-24 \r\n(действительно до \r\n08.02.2026)\r\nРезультаты контроля\r\nСплошное сканирование выполнено на секции 16630.\r\nВ ходе контроля утонения (расслоения) не выявлены. Диапазон толщин \r\nварьируется от 5,6 мм до 5,8 мм.\r\nСхема контроля представлена на рисунке 1.", "[стр. 45]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n45\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРисунок 1. – Зона сканирования.\r\nВывод\r\nВ результате сплошного ультразвукового сканирования была зафиксирована \r\nминимальная толщина 5,6 мм. \r\nПротокол подготовил, контроль выполнил:\r\nВедущий инженер,\r\nспециалист 2-го уровня по УК,\r\nудостоверение от 28.02.2025\r\n№ 0039-34502\r\n(действительно до 28.02.2028) Д.О. Нескашин", "[стр. 46]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n46\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРисунок 2. Места сплошного сканирования стенки трубопровода", "[стр. 47]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n47\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 9\r\nОбщество с ограниченной ответственностью\r\n«Уральский центр промышленной безопасности»\r\nСвидетельство об аккредитации № ИЛ/ЛРИ-00759 действительно до 27.11.2025\r\nПРОТОКОЛ\r\nИЗМЕРЕНИЯ ТВЕРДОСТИ\r\n06.10.2025 № 2-25-167-01-ТО-5\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК \r\n«Норильский никель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nЗамеры твердости материала трубопровода проведены в соответствии с \r\nдокументами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики;\r\n‒ Методика оценки остаточного ресурса технологических трубопроводов (утв. \r\nМинистерством топлива и энергетики Российской Федерации 17.07.96).\r\n‒ Инструкция по эксплуатации твердомера;\r\n‒ ГОСТ 22761-77 «Метод измерения твердости по Бринеллю переносными \r\nтвердомерами статического действия»;\r\n‒ ГОСТ. 24621-2015. Пластмассы и эбонит. Определение твердости при \r\nвдавливании с помощью дюрометра (твердость по Шору);\r\n‒ Технические условия ТУ 2258-004-45130869-2013 «Трубы и детали \r\nтрубопроводов полиуретановые».\r\nОбъём контроля\r\nЗамеры твердости основного металла и футеровки трубопровода выполнены в \r\nобъеме, предусмотренном Программой проведения диагностики футерованных\r\nтрубопроводов. Измерение твердости основного металла секций трубопровода \r\nвыполнялось в местах, подготовленных для УЗТ. \r\nСхема измерений твердости основного металла в сечениях приведена на рисунке \r\n1.", "[стр. 48]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n48\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРисунок 2. Схема измерений твердости основного металла\r\nИзмерение твердости футеровки проводилось в доступных местах – на \r\nдемонтированных секциях трубопровода.\r\nПараметры контроля\r\nУсловия контроля:\r\n‒ освещенность не менее 500 Лк;\r\n‒ шероховатость зачищенных под контроль участков основного металла не более \r\nRa 2,5 (Rz 10);\r\n‒ температура окружающей среды не превышает установленных паспортом \r\nдопустимых параметров эксплуатации приборов.", "[стр. 49]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n49\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nСредства контроля\r\nТаблица 1. Средства контроля\r\nНаименование прибора Назначение прибора Заводской \r\nномер\r\nСвидетельство о \r\nповерке\r\nТвердомер ТЭМП-4\r\nИзмерение твердости \r\nматериала\r\n400111\r\nот 18.07.2025\r\n№ С-ГХШ/18-07-\r\n2025/171325604 \r\n(действительно до \r\n17.07.2026)\r\nМера твердости 10 № \r\n9742 172 HB 10/3000/10\r\nКалибровка и контроль \r\nточности показаний \r\nприборов\r\n9742\r\nСертификат о \r\nкалибровке от \r\n26.12.2024 М.КЮС￾7348-24 \r\n(действителен до \r\n25.12.2027)\r\nПортативный твердомер \r\nпо Шору D TIME5431\r\nИзмерение твердости \r\nматериала\r\n00000605 \r\n29000010 заводская поверка\r\nМеры твердости Шора\r\nКалибровка и контроль \r\nточности показаний \r\nприборов\r\n2145 не поверяется\r\nЛюксметр Testо-540 Измерение освещенности \r\nрабочей зоны 39105292/0920\r\nот 15.01.2025\r\n№ С-ВЯ/15-01-\r\n2025/402423299 \r\n(действительно до \r\n14.01.2026)\r\nПирометр инфракрасный \r\nRGK PL-12 Измерение температуры 23052127\r\nот 03.06.2025\r\n№ С-ДДЭ/03-06-\r\n2025/437665937 \r\nдействительно до \r\n02.06.2026)\r\nНабор образцов \r\nшероховатости\r\nОпределение \r\nшероховатости \r\nповерхности\r\n0012\r\nСертификат о \r\nкалибровке от \r\n09.02.2024\r\n№ Ш.КЮС-510-24 \r\n(действительно до \r\n08.02.2026)\r\nРезультаты контроля\r\nТаблица 2. Результаты измерения твердости основного металла № секции Тип секции\r\nТвердость металла стенки трубопровода, НВ\r\nТвердость, НВ\r\n(среднее значение)\r\nсечение 1 сечение 2 сечение 3\r\n0° 90° 180° 270° 0° 90° 180° 270° 0° 90° 180° 270°\r\n16600 труба 117 121 102 113 133 118 132 121 120\r\n16630 труба 99 113 115 126 121 115 119 120 116\r\n16640 труба 110 115 117 122 131 105 134 114 119", "[стр. 50]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n50\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\n№ секции\r\nТип секции\r\nТвердость металла стенки трубопровода, НВ\r\nТвердость, НВ\r\n(среднее значение)\r\nсечение 1 сечение 2 сечение 3\r\n0° 90° 180° 270° 0° 90° 180° 270° 0° 90° 180° 270°\r\n16670 труба 117 124 99 103 127 114 122 112 115\r\n16680 труба 125 141 123 123 109 122 112 120 117\r\n16700 труба 131 129 127 104 129 119 112 119 121\r\n16750 труба 112 117 119 108 132 99 100 125 114\r\n16760 труба 105 131 99 120 130 111 112 116 116\r\n16770 труба 116 117 109 135 129 121 104 127 120\r\n16780 труба 110 119 129 135 108 127 129 107 121\r\nВывод\r\nИзмеренные значения твёрдости металла стенок трубопроводов находятся в \r\nдиапазоне 99-141 НВ, сведения о марке стали не предоставлены.\r\nИзмеренные значения твёрдости металла стенок трубопроводов находятся в \r\nдопустимых пределах для стали марки 17ГС-1 (100-170 HB в соответствии с \r\nСО 153 34.17.439–2003).\r\nПротокол подготовил, контроль выполнил:\r\nИнженер 1 категории,\r\nСпециалист по разрушающим методам контроля,\r\nудостоверение от 16.02.2024\r\n№ НОАП - 0039 – 30566(действительно до 08.12.2026) А.С. Коротаев", "[стр. 51]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n51\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nРисунок 1. Места контроля твёрдости стенки трубопровода", "[стр. 52]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n52\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 11\r\nГИДРАВЛИЧЕСКИЙ РАСЧЕТ\r\nфутерованных трубопроводов системы гидротранспорта\r\nТалнахской обогатительной фабрики \r\nВодовод от УП №1 до пруда - накопителя, инв.№ 39400183632\r\nДля выполнения расчетов отбраковочной толщины стенки (Приложение № 12) и \r\nостаточного ресурса трубопровода (Приложение № 13) в качестве исходных данных \r\nиспользуется рабочее давление среды. Расчет давления оборотной воды участка \r\nтрубопровода выполнен с помощью гидравлического моделирования в программном \r\nкомплексе ZuluHydro 10.\r\nСредствами ПО был разработан цифровой двойник участка водовода от УП №1 до \r\nпруда - накопителя, инв.№ 39400183632 и проведен поверочный гидравлический расчет.\r\nДля выполнения гидравлического расчета трубопровод был условно разделен на \r\nучастки. За нулевую точку была принята отметка оси трубопровода. В результате расчета \r\nдля каждого участка были определены подачи и напоры оборотной воды в узловых точках. \r\nИсходные данные для выполнения поверочного гидравлического расчета \r\nпредставлены в таблице 1.\r\nТаблица 1. Исходные данные для гидравлического расчета\r\n№ \r\nп/п\r\nТип \r\nэлемента\r\nНаименование Принятое \r\nзначение\r\nПримечание\r\n1\r\nУчасток\r\nОбщая \r\nпротяженность, м\r\n115 -\r\n2\r\nВнутренний диаметр \r\nтрубы, м 426 -\r\n3 Шероховатость, мм 1 -\r\n4\r\nКоэффициент \r\nместных \r\nсопротивлений\r\n1,3 Определен экспертно в виду отсутствия штатных \r\nманометров \r\n5\r\nЗарастание \r\nтрубопровода, мм 1,2\r\nСогласно справки ZuluHydro 10 \r\n(https://www.politerm.com/zuluhydro/webhelp/math_so\r\nurce_data2.html) значение принималось по таблице \r\nА.Г. Камерштейна, значение для значительного \r\nкоррозийного воздействия. Ежегодный прирост \r\nабсолютной шероховатости, 0,20 мм в год за период \r\nс 2016 г. по 2025 г.\r\n6 Узел Геодезическая \r\nотметка, м\r\n-\r\nПриняты условные геодезические отметки \r\nотносительно отметки установки насоса и длины \r\nучастков равными расстояниям между \r\nПоверочный гидравлический расчет цифрового двойника участка водовода от УП \r\n№1 до пруда - накопителя, инв.№ 39400183632 был выполнен с целью определения \r\nпотерь напора на каждом участке трубопровода. С учетом отсутствия значений \r\nфактического давления результаты поверочного расчета представлены в таблице 2.", "[стр. 53]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n53\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nТаблица 2. Сводная таблица расчета давления участка водовода от УП №1 до пруда -\r\nнакопителя, инв.№ 39400183632\r\nНомер \r\nсечени\r\nя по \r\nУЗТ\r\nДиамет\r\nр, мм\r\nКоэффициен\r\nт местных \r\nсопротивлен\r\nий\r\nЗарастание \r\nтрубопровод\r\nа, мм\r\nПотери \r\nнапора на \r\nучастке, м\r\nСкорость \r\nдвижения \r\nоборотной \r\nводы, м/с\r\nРасчетное \r\nрабочее \r\nдавление \r\nв начале \r\nучастка, \r\nМпа\r\nРасчетное \r\nдавление при \r\nгидравлическ\r\nом ударе, Мпа\r\n16600 426 1,3 1,2 2,819 1,20 1,600 2,270\r\n16630 426 1,3 1,2 2,819 1,20 1,572 2,230\r\n16640 426 1,3 1,2 2,819 1,20 1,544 2,190\r\n16670 426 1,3 1,2 2,819 1,20 1,515 2,150\r\n16680 426 1,3 1,2 2,819 1,20 1,487 2,110\r\n16700 426 1,3 1,2 2,819 1,20 1,459 2,070\r\n16750 426 1,3 1,2 2,819 1,20 1,431 2,030\r\n16760 426 1,3 1,2 2,819 1,20 1,403 1,990\r\n16770 426 1,3 1,2 2,819 1,20 1,374 1,950\r\n16780 426 1,3 1,2 2,819 1,20 1,346 1,910\r\nГлавный специалист\r\nнаправления по энергоменеджменту Голубев И.А.", "[стр. 54]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n54\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nПРИЛОЖЕНИЕ № 12\r\nОбщество с ограниченной ответственностью\r\n«Цветметэкспертиза»\r\nРАСЧЕТ ОТБРАКОВОЧНОЙ ТОЛЩИНЫ СТЕНКИ ТРУБОПРОВОДА\r\n06.10.2025 № 2-25-167-01-ТО-10\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК «Норильский \r\nникель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nРасчет отбраковочной толщины стенки трубопровода выполнен в соответствии с \r\nдокументами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики;\r\n‒ ГОСТ 32388-2013 «Технологические трубопроводы. Нормы и методы расчета на \r\nпрочность, вибрацию и сейсмические воздействия»;\r\n‒ СП103.13330.2012 Защита горных выработок от подземных и поверхностных вод.\r\nЦель расчёта\r\nОпределение отбраковочной толщины элементов трубопровода.\r\nРасчет минимальной толщины\r\nСогласно подразделу 5.5 ГОСТ 32388-2013 отбраковочная толщина деталей \r\nтрубопровода вычисляется по формуле:\r\nСогласно подразделу 7.1.1. расчетная толщина стенки трубы рассчитывается:\r\nСогласно подразделу 7.2.1. расчетная толщина стенки отвода вычисляется:\r\nДля секторных отводов, коэффициент ki вычисляют по формуле:\r\n.", "[стр. 55]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n55\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nТаблица 1. Результаты расчета отбраковочной толщины \r\nДиаметр наружный Da, мм р, МПа Марка \r\nстали*\r\n[σ], МПа* ϕw С1 [S], мм\r\n426 (труба) 1,6 09Г2С 183 1 1,0 2,9\r\nСогласно таблице 5.6 ГОСТ 32388-2013 минимальная толщина стенки труб и \r\nдеталей при эксплуатации диаметре 426 мм составляет 4,0 мм.\r\nСогласно подразделу 5.5.3 ГОСТ 32388-2013 минимальная толщина стенки труб и \r\nдеталей принимается 4,0 мм.\r\nВ соответствии п. 6.35 Строительные норма и правила. Защита горных выработок \r\nот подземных и поверхностных вод СНиП 2.06.14-85 (Зарегистрирован Росстандартом в \r\nкачестве СП 103.13330.2012) произведен расчет по прочности стенок трубопровода с \r\nучетом возможного гидравлического удара.\r\nРасчет трубопровода на гидроудар проведен в соответствии с Приложением 5 РТМ \r\n38.001-94.\r\nПовышение давления ΔРуд (Па) при гидравлическом ударе вследствие мгновенного \r\nполного прекращения движения жидкости при условии τ<2L/α (прямой гидравлический \r\nудар) следует вычислять по формуле Жуковского Н.Е.:\r\nС учетом работы деформации стенки трубы:\r\n∆𝑃уд = 𝜔0𝜌𝛼\r\nДля абсолютно жесткой трубы скорость распространения ударной волны:\r\n𝛼 = √𝐾⁄𝜌\r\nС учетом работы деформации стенки трубы:\r\n𝛼 =\r\n1\r\n√𝜌 [\r\n1\r\n𝐾\r\n+\r\n𝐷\r\n𝑠𝐸]\r\nРасчетное давление определено в соответствии с п. 6.3 Пособия по проектированию \r\nтрубопроводов, прокладываемых в подземных выработках (к ВНТП 1-86) по формуле:\r\n𝑃 = 𝑃р + к𝑃н\r\nС учетом требований п. 6.35 СП 103.13330.2012 значения Рр и Рн в формуле \r\nопределяются по формулам:\r\n𝑃р = 𝑃р + 2∆𝑃уд\r\n𝑃н = 𝑃н + 2∆𝑃уд\r\nТаблица 2. Результаты расчета отбраковочной толщины, с учетом возможного \r\nгидравлического удара \r\nДиаметр наружный\r\nDa, мм\r\nω0, м/с ρ, \r\nкг/м3\r\nα, м/с\r\nргидр, \r\nМПа\r\n[σ], \r\nМПа ϕw С1 [S], мм\r\n426 (труба) 1,735 1000 0,000007 2,27 183 1 1,0 2,3", "[стр. 56]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n56\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nВывод\r\nПо результатам расчёта отбраковочная толщина стенки трубопровода при рабочем \r\nдавлении и давлении с учетом гидроудара составила:\r\nДиаметр и элемент [Sфmin], мм\r\n[S] при рабочем давлении, \r\nмм\r\n[S] при давлении, с учетом \r\nгидроудара, мм\r\n426 (труба) 4,4 4,0 4,0\r\nРасчет выполнил:\r\nинженер инженерного отдела, \r\nудостоверение о повышении квалификации\r\nпо курсу «Расчет на прочность. \r\nРасчет остаточного ресурса ТУ и ЗС»,\r\nот 15.04.2021 рег.№ RU 1660327861 165СБ/0421-1 А.С. Ааб", "[стр. 57]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n57\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nАф =\r\n𝑆исп − 𝑆ф\r\nТ\r\nПРИЛОЖЕНИЕ № 13\r\nОбщество с ограниченной ответственностью\r\n«Цветметэкспертиза»\r\nРАСЧЕТ\r\nСКОРОСТИ КОРРОЗИИ И ОСТАТОЧНОГО РЕСУРСА ТРУБОПРОВОДА\r\n06.10.2025 № 2-25-167-01-ТО-11\r\nОбъект контроля\r\nТалнахская обогатительная фабрика, Заполярного филиала ПАО «ГМК «Норильский \r\nникель», Водовод от УП №1 до пруда - накопителя, инв.№ 39400183632.\r\nРегламентирующая документация\r\nРасчет остаточного ресурса трубопровода выполнен в соответствии с документами:\r\n‒ Программа проведения диагностики футерованных трубопроводов системы \r\nгидротранспорта Талнахской обогатительной фабрики;\r\n‒ Методика оценки остаточного ресурса технологических трубопроводов (утв. \r\nМинистерством топлива и энергетики Российской Федерации 17.07.96).\r\nЦель расчёта\r\nОпределение остаточного ресурса по минимальной фактической толщине элемента \r\nпо результатам диагностики; расчёт скорости коррозии.\r\nРасчеты\r\nОстаточный ресурс трубопровода определяется по формуле (п. 5.3 \"Методики \r\nоценки остаточного ресурса технологических трубопроводов\")\r\nгде Тост – остаточный ресурс элемента, годы; \r\nSф – фактическая толщина элемента, мм; \r\nSотб – отбраковочная толщина элемента \r\nК – коэффициент, зависящий от категории и срока службы трубопровода без \r\nзамены; \r\nАф – фактическая скорость коррозии.\r\nСредняя скорость коррозии стенки трубопровода определяется по формуле\r\nгде: Su – исполнительная толщина элемента, мм;\r\nТ – время от начала эксплуатации до момента диагностики, лет.", "[стр. 58]\nИзм. Лист № докум. Подп. Дата\r\nПодп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Инв. № подл.\r\nЛист\r\n58\r\nНО/ЗФ/2025/846.ДФТ.ТОФ.ТО\r\nТаблица 1. Результаты расчета остаточного ресурса\r\nНомер \r\nсечения по \r\nУЗТ\r\nДиаметр, \r\nмм\r\nSотб, мм SФ, мм Sи, мм t1, лет К\r\nАф, \r\nмм/год Тост, лет\r\n16600 426 4,0 6,7 7,0 9 1 0,033 >8\r\n16630 426 4,0 5,6 6,0 9 1 0,044 >8\r\n16640 426 4,0 5,7 6,0 9 1 0,033 >8\r\n16670 426 4,0 6,8 7,0 9 1 0,022 >8\r\n16680 426 4,0 6,5 7,0 9 1 0,056 >8\r\n16700 426 4,0 6,8 7,0 9 1 0,022 >8\r\n16750 426 4,0 5,8 6,0 9 1 0,022 >8\r\n16760 426 4,0 5,7 6,0 9 1 0,033 >8\r\n16770 426 4,0 5,7 6,0 9 1 0,033 >8\r\n16780 426 4,0 8,1 8,0 9 1 0,000 >8\r\nВывод\r\nМаксимальная рассчитанная равномерная скорость коррозии – 0,056 мм в год на \r\nсекции 16680. \r\nОстаточный ресурс всех секции – 8 лет.\r\nРасчет выполнил:\r\nинженер инженерного отдела, \r\nудостоверение о повышении квалификации\r\nпо курсу «Расчет на прочность. \r\nРасчет остаточного ресурса ТУ и ЗС»,\r\nот 15.04.2021 рег.№ RU 1660327861 165СБ/0421-1 А.С. Ааб", "[стр. 59]\nИзм. Лист № докум. Подп. Дата\r\nИнв. № подл. Подп. и дата Взам.инв. № Инв.№ дубл. Подп. и дата Лист 59 НО/ЗФ/2025/846.Д\r\nФТ.ТОФ.ТО\r\nРисунок 1. Водовод от УП №1 до пруда-накопителя», инв.№ 39400183632"]};
